      "support_status": "SUFFICIENT",
      "rationale": "P025 explicitly makes compatibility with existing equipment a condition of trial selection."
    }
  },
  "signal_basis": {
    "component_id": "C042.signal_basis",
    "value": "Removal tests keep equipment, the agreed deadline and other test conditions fixed. A smaller configuration repeatedly reproduces lateness while specified further removals cease to do so, using a common repetition rule and treating inconsistent outcomes as unresolved.",
    "scope": "Reduction testing of the selected late case.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "CONTEXT"
        },
