        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish the selected case, fixed test conditions, repetition and uncertainty rules, and observed reduction pattern."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C042.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This explicit selection constraint requires no unresolved empirical relation."
    }
  },
  "rationale": "The claim is a resource constraint explicitly imposed on selecting a trial from the test findings. Within that limited scope it is supported; it does not assert that the reduction signal proves an equipment-compatible trial exists or will succeed.",
  "uncertainty": "Whether a particular proposed trial meets the constraint remains to be assessed, but that does not undermine the stated requirement.",
